  `tenant_type` enum('CHAIN','BRANCH','INDEPENDENT') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '租户类型：连锁店/分店/独立商户',
  `parent_tenant_id` bigint DEFAULT NULL COMMENT '父租户ID（分店关联总部）',
  `status` enum('ACTIVE','INACTIVE','SUSPENDED') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'ACTIVE' COMMENT '状态',
