INSERT INTO `notification_templates` (`id`, `tenant_id`, `template_code`, `template_name`, `type`, `subject`, `content`, `status`, `created_at`, `updated_at`) VALUES (7,1,'APPOINTMENT_CONFIRMATION','Appointment Confirmation SMS Template','SMS','','【${businessName}】Hi ${customerName}, your ${serviceName} appointment with ${staffName} is confirmed for ${appointmentDate} at ${appointmentTime}. Call ${businessPhone} to modify or cancel.','ACTIVE','2025-11-03 13:53:48','2025-11-10 23:55:53'),(8,1,'APPOINTMENT_CONFIRMATION','Appointment Confirmation Email Template','EMAIL','Appointment Confirmation - ${businessName}','<html>\n  <body style=\"font-family: Arial, sans-serif; background-color: #f9f9f9; padding: 20px; color: #333;\">\n    <div style=\"max-width: 600px; margin: 0 auto; background: #fff; border-radius: 8px; box-shadow: 0 2px 6px rgba(0,0,0,0.05); padding: 24px;\">\n      <h2 style=\"color: #2c3e50; text-align: center; margin-bottom: 20px;\">Appointment Confirmation</h2>\n\n      <p>Dear <strong>${customerName}</strong>,</p>\n      <p>Your appointment has been <strong>successfully confirmed</strong>. Please find the details below:</p>\n\n      <table style=\"width: 100%; border-collapse: collapse; margin: 16px 0; font-size: 14px;\">\n        <tr style=\"background-color: #f4f6f8;\">\n          <td style=\"padding: 10px; border: 1px solid #ddd;\"><strong>Appointment Time</strong></td>\n          <td style=\"padding: 10px; border: 1px solid #ddd;\">${appointmentDate} ${appointmentTime}</td>\n        </tr>\n        <tr>\n          <td style=\"padding: 10px; border: 1px solid #ddd;\"><strong>Service</strong></td>\n          <td style=\"padding: 10px; border: 1px solid #ddd;\">${serviceName}</td>\n        </tr>\n        <tr style=\"background-color: #f4f6f8;\">\n          <td style=\"padding: 10px; border: 1px solid #ddd;\"><strong>Staff</strong></td>\n          <td style=\"padding: 10px; border: 1px solid #ddd;\">${staffName}</td>\n        </tr>\n        <tr>\n          <td style=\"padding: 10px; border: 1px solid #ddd;\"><strong>Duration</strong></td>\n          <td style=\"padding: 10px; border: 1px solid #ddd;\">${duration} minutes</td>\n        </tr>\n        <tr style=\"background-color: #f4f6f8;\">\n          <td style=\"padding: 10px; border: 1px solid #ddd;\"><strong>Amount</strong></td>\n          <td style=\"padding: 10px; border: 1px solid #ddd;\">${totalAmount}</td>\n        </tr>\n      </table>\n\n      <p style=\"margin-top: 20px;\">\n        <strong>Business Info:</strong><br/>\n        ${businessName}<br/>\n        ${businessAddress}<br/>\n        ${businessPhone}\n      </p>\n\n      <p style=\"margin-top: 24px;\">\n        To cancel or modify your appointment, please contact us directly.<br/>\n        Thank you for your trust and we look forward to seeing you soon!\n      </p>\n\n      <p style=\"font-size: 12px; color: #888; text-align: center; margin-top: 30px;\">\n        © ${businessName} | VA Merchant System\n      </p>\n    </div>\n  </body>\n</html>\n','ACTIVE','2025-11-03 13:53:48','2025-11-11 18:02:11'),(9,1,'APPOINTMENT_CANCELLATION','Appointment Cancellation SMS Template','SMS','','【${businessName}】Hi ${customerName}, your ${serviceName} appointment on ${appointmentDate} at ${appointmentTime} has been cancelled. Please call ${businessPhone} if you have questions.','ACTIVE','2025-11-03 13:53:48','2025-11-10 23:57:54'),(10,1,'APPOINTMENT_CANCELLATION','Appointment Cancellation Email Template','EMAIL','Appointment Cancellation - ${businessName}','<html>\n  <body style=\"font-family: Arial, sans-serif; background-color: #f9f9f9; padding: 20px; color: #333;\">\n    <div style=\"max-width: 600px; margin: 0 auto; background: #fff; border-radius: 8px; box-shadow: 0 2px 6px rgba(0,0,0,0.05); padding: 24px;\">\n      <h2 style=\"color: #2c3e50; text-align: center; margin-bottom: 20px;\">Appointment Cancelled</h2>\n      <p>Dear <strong>${customerName}</strong>,</p>\n      <p>Your appointment has been <stron